package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Attribute_getValue_TriageGen2Test {

    private Attribute attr1;
    private Attribute attr2;
    private Attribute attr3;

    @Before
    public void setUp() {
        attr1 = new Attribute("key1", "value1");
        attr2 = new Attribute("key2", "value2");
        attr3 = new Attribute("key3", "", new Attributes());
    }

    @Test
    public void testGetValue_ReturnsCorrectValue() {
        assertEquals("value1", attr1.getValue());
        assertEquals("value2", attr2.getValue());
    }

    @Test
    public void testGetValue_ReturnsEmptyStringForEmptyValue() {
        assertEquals("", attr3.getValue());
    }

    @Test
    public void testGetValue_VerifyNullKeyDoesNotAffectValue() {
        Attribute attr4 = new Attribute(null, "value3");
        assertEquals("value3", attr4.getValue());
    }

    @Test
    public void testGetValue_WithParentAttributes() {
        Attributes parent = new Attributes();
        parent.attr("parentKey", "parentValue");
        Attribute attr5 = new Attribute("key4", "value4", parent);
        assertEquals("value4", attr5.getValue());
    }

    @Test
    public void testGetValue_ConstantBranchCoverage() {
        // Ensuring that getValue is tested with various combinations
        assertEquals("value1", attr1.getValue());
        assertEquals("value2", attr2.getValue());
        assertEquals("", attr3.getValue());
        assertEquals("value3", new Attribute(null, "value3").getValue());
        assertEquals("value4", new Attribute("key4", "value4", new Attributes()).getValue());
    }
}
